import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"TLS, authentication and permissions","description":"","frontmatter":{"pageId":"admins/security-auth","contentRevision":1},"headers":[],"relativePath":"en/admins/security-auth.md","filePath":"en/admins/security-auth.md"}'),s={name:"en/admins/security-auth.md"};function r(o,e,d,l,c,u){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="tls-authentication-and-permissions" tabindex="-1">TLS, authentication and permissions <a class="header-anchor" href="#tls-authentication-and-permissions" aria-label="Permalink to &quot;TLS, authentication and permissions&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>TLS is enabled by default. Set PEM CertificatePath/KeyPath or use a self-signed certificate; distribute its pin through an independent channel. SelfSignedPath selects the self-signed certificate path. Plan certificate rotation in advance.</p><p>Steam authentication requires SteamWebApiKey and administrative Steam IDs as appropriate. AllowPassword enables password accounts; AdminLogins assigns initial administrators. ServerPassword is not a replacement for personal authentication.</p><p>Give each integration a separate Admin:Tokens entry with Name, Token and Scopes. Names are unique, [a-z0-9-], up to 32 characters; tokens are unique and at least 24 characters. read reads, moderate includes read, chat permits external chat, and admin grants all permissions. Minimize scope.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>The panel uses legacy Admin:ApiToken, not named tokens. Its cookie is HttpOnly/Secure/SameSite=Strict; in-memory sessions end on restart; 5 failures lock an IP for 10 minutes. Cookie mutations require CSRF. Do not use --insecure outside an isolated test. X-Rimlink-Actor is a 1–64-character audit label without controls, not proof of identity.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./api">REST API reference</a></li><li><a href="./administration">Panel and moderation</a></li><li><a href="./discord">Discord bot</a></li></ul>',10)])])}const p=a(s,[["render",r]]);export{m as __pageData,p as default};
